DO $test$
DECLARE
  mario uuid; luca uuid; staff uuid; tenant uuid; pet uuid; service uuid;
  alternatives jsonb; first_day date; first_preference text;
  request public.appointment_requests; result jsonb := '{}'::jsonb;
  baseline_requests integer; baseline_appointments integer; visible_appointments integer;
  changed integer; msg text;
BEGIN
  SELECT id INTO STRICT mario FROM auth.users WHERE email='mario.rossi@test.example';
  SELECT id INTO STRICT luca FROM auth.users WHERE email='luca.bianchi@test.example';
  SELECT id INTO STRICT staff FROM auth.users WHERE email='staff.sonda@test.example';
  SELECT p.id,p.tenant_id INTO STRICT pet,tenant FROM public.pets p
    JOIN public.customers c ON c.id=p.customer_id WHERE c.user_id=mario ORDER BY p.id LIMIT 1;
  SELECT id INTO STRICT service FROM public.services WHERE tenant_id=tenant AND is_active ORDER BY display_order,id LIMIT 1;
  SELECT jsonb_agg(jsonb_build_object('date',slot_day::text,'time_preference',preference) ORDER BY slot_day,preference) INTO alternatives
  FROM (
    SELECT current_date + g AS slot_day, preference FROM generate_series(1,30) g
    CROSS JOIN (VALUES ('morning'),('afternoon')) bands(preference)
    JOIN public.tenants t ON t.id=tenant
    WHERE NOT coalesce(t.settings #> '{booking_schedule,closed_weekdays}','[]'::jsonb) ? (ARRAY['sunday','monday','tuesday','wednesday','thursday','friday','saturday'])[extract(dow FROM current_date+g)::int+1]
      AND NOT coalesce(t.settings #> ARRAY['booking_schedule','closed_time_preferences',(ARRAY['sunday','monday','tuesday','wednesday','thursday','friday','saturday'])[extract(dow FROM current_date+g)::int+1]],'[]'::jsonb) ? preference
    ORDER BY slot_day,preference LIMIT 2
  ) slots;
  IF jsonb_array_length(alternatives)<>2 THEN RAISE EXCEPTION 'Two open slots required'; END IF;
  first_day := (alternatives->0->>'date')::date; first_preference := alternatives->0->>'time_preference';
  SELECT count(*) INTO baseline_requests FROM public.appointment_requests;
  SELECT count(*) INTO baseline_appointments FROM public.appointments;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',mario,'role','authenticated')::text,true);
    SELECT count(*) INTO visible_appointments FROM public.appointments;
    SELECT * INTO request FROM public.submit_appointment_request(tenant,pet,service,first_day,first_preference,ARRAY['some_knots'],'[DEMO GH-87] alternative-response probe',NULL);
    result := result || jsonb_build_object('request_id',request.id,'alternatives',alternatives,'before',jsonb_build_object('status',request.status,'chosen_date',request.chosen_date,'chosen_time_preference',request.chosen_time_preference,'customer_response',request.customer_response,'customer_responded_at',request.customer_responded_at));
    PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',staff,'role','authenticated')::text,true);
    result := result || jsonb_build_object('staff_pending_before_proposal',(SELECT count(*) FROM public.appointment_requests WHERE status='pending' AND tenant_id=tenant));
    PERFORM public.propose_appointment_request_alternatives(request.id,alternatives);
    result := result || jsonb_build_object('staff_pending_after_proposal',(SELECT count(*) FROM public.appointment_requests WHERE status='pending' AND tenant_id=tenant));
    PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',luca,'role','authenticated')::text,true);
    BEGIN
      PERFORM public.respond_appointment_request_alternatives(request.id,'accepted',first_day,first_preference);
      RAISE EXCEPTION 'Foreign customer unexpectedly allowed';
    EXCEPTION WHEN SQLSTATE '42501' THEN
      GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
      result := result || jsonb_build_object('foreign_customer',jsonb_build_object('code',SQLSTATE,'message',msg));
    END;
    PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',mario,'role','authenticated')::text,true);
    UPDATE public.appointment_requests SET customer_response='declined' WHERE id=request.id;
    GET DIAGNOSTICS changed = ROW_COUNT;
    IF changed<>0 THEN RAISE EXCEPTION 'Direct customer write unexpectedly allowed'; END IF;
    result := result || jsonb_build_object('direct_update_rows',changed,'invoker_role',current_user);
    BEGIN
      PERFORM public.respond_appointment_request_alternatives(request.id,'accepted',first_day+365,first_preference);
      RAISE EXCEPTION 'Unproposed pair unexpectedly allowed';
    EXCEPTION WHEN SQLSTATE '22023' THEN
      GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
      result := result || jsonb_build_object('unproposed_pair',jsonb_build_object('code',SQLSTATE,'message',msg));
    END;
    PERFORM public.respond_appointment_request_alternatives(request.id,'accepted',first_day,first_preference);
    SELECT * INTO request FROM public.appointment_requests WHERE id=request.id;
    IF request.status<>'pending' OR request.customer_response<>'accepted' OR request.appointment_id IS NOT NULL THEN RAISE EXCEPTION 'Accepted invariant failed'; END IF;
    result := result || jsonb_build_object('accepted_readback',jsonb_build_object('status',request.status,'chosen_date',request.chosen_date,'chosen_time_preference',request.chosen_time_preference,'customer_response',request.customer_response,'customer_responded_at',request.customer_responded_at,'appointment_id',request.appointment_id));
    PERFORM public.respond_appointment_request_alternatives(request.id,'declined',NULL,NULL);
    SELECT * INTO request FROM public.appointment_requests WHERE id=request.id;
    IF request.status<>'pending' OR request.customer_response<>'declined' OR request.chosen_date IS NOT NULL OR request.chosen_time_preference IS NOT NULL THEN RAISE EXCEPTION 'Declined invariant failed'; END IF;
    result := result || jsonb_build_object('declined_readback',jsonb_build_object('status',request.status,'chosen_date',request.chosen_date,'chosen_time_preference',request.chosen_time_preference,'customer_response',request.customer_response,'customer_responded_at',request.customer_responded_at,'appointment_id',request.appointment_id),'customer_appointments_before',visible_appointments,'customer_appointments_after',(SELECT count(*) FROM public.appointments));
    PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',staff,'role','authenticated')::text,true);
    UPDATE public.appointment_requests SET status='rejected' WHERE id=request.id;
    PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',mario,'role','authenticated')::text,true);
    BEGIN
      PERFORM public.respond_appointment_request_alternatives(request.id,'accepted',first_day,first_preference);
      RAISE EXCEPTION 'Resolved request unexpectedly allowed';
    EXCEPTION WHEN SQLSTATE '23514' THEN
      GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
      result := result || jsonb_build_object('resolved_request',jsonb_build_object('code',SQLSTATE,'message',msg));
    END;
    RAISE EXCEPTION 'Rollback all fixture writes' USING ERRCODE='P0087';
  EXCEPTION WHEN SQLSTATE 'P0087' THEN NULL;
  END;
  IF (SELECT count(*) FROM public.appointment_requests)<>baseline_requests OR (SELECT count(*) FROM public.appointments)<>baseline_appointments THEN RAISE EXCEPTION 'Rollback count mismatch'; END IF;
  result := result || jsonb_build_object('requests_before',baseline_requests,'requests_after_rollback',(SELECT count(*) FROM public.appointment_requests),'appointments_before',baseline_appointments,'appointments_after_rollback',(SELECT count(*) FROM public.appointments),'fixture_residue',(SELECT count(*) FROM public.appointment_requests WHERE coat_condition_notes LIKE '[DEMO GH-87]%'));
  PERFORM set_config('gh87.test_result',result::text,false);
END
$test$;
SELECT current_setting('gh87.test_result')::jsonb AS evidence;
